    {
      "@id": "entity:source-meet_peri.step.4.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child proposes a cause or mechanism. Peri tests it with evidence questions, not hints."
    },
    {
      "@id": "entity:target-meet_peri.step.4.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "您的孩子提出一种原因或机制。皮里用证据问题而不是提示来测试它。",
